SELECT pl.category_id AS categoryId, c.category_name AS categoryName, SUM(pl.raw_stone_cost) AS totalRawStoneCost, SUM(pl.material_cost) AS totalMaterialCost, SUM(pl.labor_cost) AS totalLaborCost, SUM(pl.total_cost) AS totalCost, SUM(pl.order_income) AS totalIncome, SUM(pl.profit_amount) AS totalProfit, AVG(pl.profit_rate) AS avgProfitRate, COUNT(*) AS orderCount FROM profit_ledger pl LEFT JOIN amber_category c ON pl.category_id = c.id
pl.deleted = 0
AND pl.ledger_date >= #{startDate}
AND pl.ledger_date <= #{endDate}
GROUP BY pl.category_id, c.category_name ORDER BY totalProfit DESC
